dep=report['inherited_pin_source'];b=(ROOT/dep['path']).read_bytes();need(digest(b)==dep['sha256'],'previous pin')
prev=json.loads(b);olddep=prev['inherited_pin_source'];b=(ROOT/olddep['path']).read_bytes();need(digest(b)==olddep['sha256'],'old pin')
old=json.loads(b);pins=dict(old['code_doc_sha256']);pins[olddep['path']]=olddep['sha256'];pins.update(prev['own_code_doc_sha256']);pins[dep['path']]=dep['sha256']
