def integer(w):
    need(type(w) is list and len(w)==16 and all(type(x) is int and 0<=x<2**32 for x in w),'uint32')
    n=sum(x<<(32*i) for i,x in enumerate(w));return n-2**512 if n>=2**511 else n
def cmpwords(a,b):
    diff=a^b;return 16 if not diff else 16-((diff.bit_length()-1)//32)
def check(v):
    n,d=integer(v['length_words']),integer(v['wavelength_words']);need(d>0,'wavelength')
    q,r=divmod(n,d);ct=(2*n+d)//(2*d);cn=n-ct*d
    need(integer(v['floor_turn_words'])==q and integer(v['euclidean_remainder_words'])==r,'Euclidean')
    need(integer(v['centered_turn_words'])==ct and integer(v['centered_numerator_words'])==cn,'centered')
    need(v['centered_denominator_words']==v['wavelength_words'] and v['half_tie_negative']==(2*r==d),'den/tie')
    need(Fraction(-1,2)<=Fraction(cn,d)<Fraction(1,2),'range')
    need(v['new_rounding_phase_error']==[0,1] and v['exact_rational_cycles_CPU_only'] is True,'exact')
    for k in ('phase_unit_evaluated','accepted_full_field_pipeline','GPU_executed'):need(v[k] is False,'no promotion')
    remainder=quotient=compare=subtract=inc=0;mag=abs(n)
    for bit in range(511,-1,-1):
        remainder=(remainder<<1)|((mag>>bit)&1);compare+=cmpwords(remainder,d)
        if remainder>=d:remainder-=d;quotient|=1<<bit;subtract+=16
    if n<0 and remainder:
        inc=1
        while (quotient&0xffffffff)==0xffffffff:inc+=1;quotient>>=32
        remainder=d-remainder;subtract+=16
    subtract+=16;compare+=cmpwords(remainder,d-remainder)
    expected={'bit_rounds':512,'unsigned_shift_words':8192,'unsigned_compare_words':compare,'unsigned_subtract_words':subtract,'unsigned_increment_words':inc}
