            for v in corners:check(v)
            same=all(c['centered_turn_words']==original['centered_turn_words'] for c in corners)
            need(row['accepted_centered_branch_CPU_only'] is same and row['original_is_NOT_encoded_nominal'] is True,'selector/gauge')
            if not same:need(row['reason']=='centered branch crosses exact half turn; no epsilon or snapping','branch STOP')
            branches+=same;scene_reductions+=5;scenevals.extend([original]+corners)
