    for k in ('phase_unit_evaluated','field_values_computed','accepted_full_field_pipeline','GLSL_compiled','GPU_executed','GPU_job_admission','execution_authenticated'):need(out[k] is False,'no field/native')
need((len(raw['cases']),source_count,evals,stops,scene_reductions)==(17,19,8,11,40),'counts')
need(len(raw['primitives'])==130,'130 vectors')
lo=-(1<<511);hi=(1<<511)-1;rng=random.Random(20261001)
pairs=[(n,d) for n in (lo,lo+1,-(1<<510),-7,-1,0,1,7,1<<510,hi-1,hi) for d in (1,2,3,17,1<<510,hi)]
pairs += [(rng.randrange(lo,hi+1),rng.randrange(1,hi+1)) for _ in range(64)]
need([(integer(v['length_words']),integer(v['wavelength_words'])) for v in raw['primitives']]==pairs,'actual signed boundary/random vectors')
for v in raw['primitives']:check(v)
control=raw['selector_control'];a=check(control['original'])
for v in control['crossing_corners']+control['same_corners']:check(v)
need(len(control['crossing_corners'])==len(control['same_corners'])==4,'branch control count')
need(not all(c['centered_turn_words']==a['centered_turn_words'] for c in control['crossing_corners']),'crossing STOP')
need(all(c['centered_turn_words']==a['centered_turn_words'] for c in control['same_corners']),'same PASS')
need(len(raw['reduction_calls'])==193 and len(raw['expected_rejections'])==8,'all valid/invalid calls')
for v in raw['reduction_calls']:check(v)
def validwords(w):return type(w) is list and len(w)==16 and all(type(x) is int and 0<=x<2**32 for x in w)
for reject in raw['expected_rejections']:
    args=reject['inputs'];kw=reject['kwargs'];need(len(args)==2 and reject['type'] in ('ValueError','TypeError'),'rejection type')
    valid=(kw.get('model')=='axial-16limb-euclidean-centered-cycles-CPU-v1' and validwords(args[0]) and validwords(args[1]))
    if valid:valid=integer(args[1])>0
    need(not valid and bool(reject['reason']),'only invalid inputs rejected')
calls=Counter(canon(v) for v in raw['reduction_calls']);expected=Counter(canon(v) for v in scenevals+raw['primitives']+[control['original']]+control['crossing_corners']+control['same_corners'])
need(not (expected-calls),'all scenario calls captured')
tree=ast.parse((ROOT/'Blender/benchmarks/capacity_audit/axial_native_quotient_v1.py').read_text(encoding='utf-8'))
for node in ast.walk(tree):
    if isinstance(node,ast.Constant):need(not isinstance(node.value,float),'float')
    if isinstance(node,ast.Call) and isinstance(node.func,ast.Name):need(node.func.id not in ('float','Fraction','sum','divmod'),'bigint helper')
    if isinstance(node,ast.BinOp) and isinstance(node.op,(ast.Div,ast.FloorDiv)):need(isinstance(node.left,ast.Name) and node.left.id=='bit' and isinstance(node.right,ast.Constant) and node.right.value==32,'only index division')
print(json.dumps({'PASS':True,'pins':len(pins)+len(report['own_code_doc_sha256']),'inherited_pins':len(pins),'cases':17,'sources':19,'scene_sources_evaluated':evals,'upstream_STOP':stops,'centered_branch_PASS':branches,'centered_branch_STOP':evals-branches,'scene_reductions':40,'primitive_vectors':130,'all_valid_reductions':193,'expected_rejections':8,'all_bit_rounds':193*512,'all_unsigned_word_shifts':193*8192,'core_frozen_unchanged':True,'GPU_executed':False,'accepted_full_field_pipeline':False},sort_keys=True))

